enum OrbKernel {
    struct WorkfoldVerdict: Equatable, Sendable {
        let foldItem: Bool
        let foldHasToolNext: Bool
    }

    @inline(__always)
    private static func b8(_ v: Bool) -> UInt8 { v ? 1 : 0 }

    @inline(__always)
    private static func satU8(_ v: Int) -> UInt8 {
        v < 0 ? 0 : (v > 255 ? 255 : UInt8(v))
    }

    @inline(__always)
    static func satU32(_ v: Int) -> UInt32 {
        v < 0 ? 0 : (v > Int(UInt32.max) ? UInt32.max : UInt32(v))
    }

    @inline(__always)
    static func satU32(_ v: Double) -> UInt32 {
        guard v.isFinite, v > 0 else { return 0 }
        let r = v.rounded()
        if r >= Double(UInt32.max) { return UInt32.max }
        return UInt32(r)
    }

    @inline(__always)
    private static func satU64(_ v: Int) -> UInt64 {
        v < 0 ? 0 : UInt64(v)
    }

    static func workfoldStep(
        itemKind: Int,
        isCumulative: Bool,
        isNonEmpty: Bool,
        toolAhead: Bool,
        nextIsTool: Bool,
        foldHasTool: Bool
    ) -> WorkfoldVerdict {
        let raw = orb_workfold_step(
            satU8(itemKind),
            b8(isCumulative),
            b8(isNonEmpty),
            b8(toolAhead),
            b8(nextIsTool),
            b8(foldHasTool)
        )
        return WorkfoldVerdict(foldItem: (raw & 1) != 0, foldHasToolNext: ((raw >> 8) & 1) != 0)
    }

    static func relativeTimeString(elapsedSecs: Int) -> String {
        let raw = orb_relative_time_bucket(satU64(elapsedSecs))
        let unit = Int(raw & 0xFF)
        let value = Int((raw >> 8) & 0xFFFF_FFFF)
        switch unit {
        case 0: return "now"
        case 1: return "\(value)m"
        case 2: return "\(value)h"
        case 3: return "\(value)d"
        default: return "\(value)w"
        }
    }

    static func usageLimitBadge(
        status: String,
        claim: String,
        hasUtilization: Bool,
        utilizationPct: Int,
        hasReset: Bool,
        resetRemSecs: Int
    ) -> (tone: String, label: String)? {
        let statusKind: UInt8
        switch status {
        case "", "allowed", "ok": statusKind = 0
        case "allowed_warning": statusKind = 1
        case "rejected": statusKind = 2
        default: statusKind = 3
        }
        let claimKind: UInt8
        switch claim {
        case "five_hour": claimKind = 1
        case "seven_day": claimKind = 2
        case "seven_day_opus": claimKind = 3
        case "seven_day_sonnet": claimKind = 4
        default: claimKind = 0
        }
        let raw = orb_usage_limit_status(
            statusKind,
            claimKind,
            b8(hasUtilization),
            satU8(utilizationPct),
            b8(hasReset),
            satU64(resetRemSecs)
        )
        let tone = Int(raw & 0xFF)
        if tone == 0 { return nil }
        if tone == 1 {
            let winKind = Int((raw >> 8) & 0xFF)
            let winLabel: String
            switch winKind {
            case 1: winLabel = "5h"
            case 2: winLabel = "weekly"
            case 3: winLabel = "weekly Opus"
            case 4: winLabel = "weekly Sonnet"
            default: return ("warning", "Approaching limit")
            }
            let showPct = ((raw >> 16) & 1) != 0
            let pct = Int((raw >> 24) & 0xFF)
            let suffix = showPct ? " \(pct)%" : ""
            return ("warning", "Approaching limit · \(winLabel)\(suffix)")
        }
        if tone == 2 {
            let resetUnit = Int((raw >> 32) & 0xFF)
            let resetVal = Int((raw >> 40) & 0xFFFFFF)
            if resetUnit == 0 { return ("error", "Limit reached") }
            let unitSuffix = resetUnit == 1 ? "m" : (resetUnit == 2 ? "h" : "d")
            return ("error", "Limit reached · resets in \(resetVal)\(unitSuffix)")
        }
        return ("warning", "Limit status unknown")
    }

